// Byte-level tests for the RDL2-compatible varint codec.
//
// Golden byte vectors follow directly from the documented wire format
// (LEB128 + zig-zag, verified against scene_rdl2 @ d3da034
// ValueContainerUtil.h). The Milestone 2 acceptance gate additionally
// cross-checks these bytes against fixtures generated by unmodified upstream
// code on Linux (docs/HISTORICAL_WINDOWS_PORT_AUDIT.md, M2 phase 0).

#include "TestHarness.h"

#include <portable/Varint.h>

#include <cstdint>
#include <cstring>

using namespace openmoonray_anari::portable;

namespace {

void checkBytes(uint64_t value, const unsigned char *expected, std::size_t expectedSize)
{
    unsigned char buffer[kVarintMaxSize64] = {};
    const std::size_t size = encodeVarint64(value, buffer);
    CHECK_EQ(size, expectedSize);
    CHECK_EQ(encodedVarintSize64(value), expectedSize);
    CHECK(std::memcmp(buffer, expected, expectedSize) == 0);

    uint64_t decoded = 0;
    CHECK_EQ(decodeVarint64(buffer, sizeof(buffer), decoded), expectedSize);
    CHECK_EQ(decoded, value);
}

} // namespace

int main()
{
    // Golden vectors per the LEB128 wire format.
    {
        const unsigned char e[] = {0x00};
        checkBytes(0, e, 1);
    }
    {
        const unsigned char e[] = {0x01};
        checkBytes(1, e, 1);
    }
    {
        const unsigned char e[] = {0x7F};
        checkBytes(127, e, 1);
    }
    {
        const unsigned char e[] = {0x80, 0x01};
        checkBytes(128, e, 2);
    }
    {
        const unsigned char e[] = {0xAC, 0x02};
        checkBytes(300, e, 2);
    }
    {
        const unsigned char e[] = {0xFF, 0x7F};
        checkBytes(16383, e, 2);
    }
    {
        const unsigned char e[] = {0x80, 0x80, 0x01};
        checkBytes(16384, e, 3);
    }
    {
        const unsigned char e[] = {0xFF, 0xFF, 0xFF, 0xFF, 0x0F};
        checkBytes(0xFFFFFFFFull, e, 5);
    }
    {
        const unsigned char e[] = {0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0xFF, 0x01};
        checkBytes(0xFFFFFFFFFFFFFFFFull, e, 10);
    }

    // Zig-zag mapping table from the upstream header documentation:
    // 0<->0, -1<->1, 1<->2, -2<->3, 2<->4, INT32_MAX<->4294967294,
    // INT32_MIN<->4294967295.
    CHECK_EQ(zigZagEncode32(0), 0u);
    CHECK_EQ(zigZagEncode32(-1), 1u);
    CHECK_EQ(zigZagEncode32(1), 2u);
    CHECK_EQ(zigZagEncode32(-2), 3u);
    CHECK_EQ(zigZagEncode32(2), 4u);
    CHECK_EQ(zigZagEncode32(INT32_MAX), 4294967294u);
    CHECK_EQ(zigZagEncode32(INT32_MIN), 4294967295u);
    CHECK_EQ(zigZagEncode64(INT64_MIN), 0xFFFFFFFFFFFFFFFFull);
    CHECK_EQ(zigZagEncode64(INT64_MAX), 0xFFFFFFFFFFFFFFFEull);

    // Signed round-trips over the LLP64-sensitive boundary set. Encoded-length
    // assertions catch width truncation that a round-trip alone would miss
    // (the historical port's 32-bit `unsigned long` produced 5-byte encodings
    // where 10 bytes are required).
    const int64_t signedCases[] = {
        0, 1, -1, 63, 64, 127, 128, 129, 16383, 16384,
        2097151, 2097152, 268435455, 268435456,
        INT32_MAX, INT32_MIN, static_cast<int64_t>(UINT32_MAX),
        1ll << 31, 1ll << 32, (1ll << 53), INT64_MAX, INT64_MIN,
    };
    for (int64_t value : signedCases) {
        unsigned char buffer[kVarintMaxSize64] = {};
        const std::size_t size = encodeVarintSigned64(value, buffer);
        CHECK(size >= 1 && size <= kVarintMaxSize64);
        int64_t decoded = 0;
        CHECK_EQ(decodeVarintSigned64(buffer, sizeof(buffer), decoded), size);
        CHECK_EQ(decoded, value);
        CHECK_EQ(size, encodedVarintSize64(zigZagEncode64(value)));

        CHECK_EQ(zigZagDecode64(zigZagEncode64(value)), value);
    }

    // INT64_MIN/MAX need the full 10 bytes; INT32-range values must not.
    CHECK_EQ(encodedVarintSize64(zigZagEncode64(INT64_MIN)), kVarintMaxSize64);
    CHECK_EQ(encodedVarintSize64(zigZagEncode64(INT64_MAX)), kVarintMaxSize64);
    CHECK(encodedVarintSize64(zigZagEncode64(-1)) == 1);

    // 32-bit signed round-trip.
    const int32_t signed32Cases[] = {0, 1, -1, INT32_MAX, INT32_MIN, 123456, -123456};
    for (int32_t value : signed32Cases) {
        unsigned char buffer[kVarintMaxSize64] = {};
        const std::size_t size = encodeVarintSigned32(value, buffer);
        CHECK(size >= 1 && size <= kVarintMaxSize32);
        int32_t decoded = 0;
        CHECK_EQ(decodeVarintSigned32(buffer, sizeof(buffer), decoded), size);
        CHECK_EQ(decoded, value);
    }

    // Malformed input: truncated stream (all continuation bits) must fail,
    // not read out of bounds.
    {
        const unsigned char truncated[] = {0x80, 0x80, 0x80};
        uint64_t decoded = 0;
        CHECK_EQ(decodeVarint64(truncated, sizeof(truncated), decoded), 0u);
    }
    // Over-long stream (>10 continuation bytes) must fail.
    {
        unsigned char overlong[12];
        std::memset(overlong, 0x80, sizeof(overlong));
        uint64_t decoded = 0;
        CHECK_EQ(decodeVarint64(overlong, sizeof(overlong), decoded), 0u);
    }

    return TEST_MAIN_RESULT();
}
